   100	export function verifyNativeReviewInvocationAttestation(args: {
   101	  attestation: SignedNativeReviewInvocationAttestation;
   102	  trustedBrokers: readonly NativeReviewBrokerRegistration[];
   103	  expected: NativeReviewInvocationExpected;
   104	  now?: number;
   105	  requireFresh?: boolean;
   106	}): NativeReviewInvocationVerification {
   107	  const claims = unsignedAttestation(args.attestation);
   108	  if (!validClaims(claims)) return { ok: false, reason: 'native invocation attestation claims are malformed' };
   109	  const matchingBrokers = args.trustedBrokers.filter(candidate =>
   110	    candidate.brokerId === claims.brokerId
   111	    && candidate.adapterId === claims.adapterId
   112	    && candidate.host === claims.host);
   113	  if (matchingBrokers.length !== 1) {
   114	    return { ok: false, reason: 'native invocation attestation issuer is not one uniquely registered host broker' };
   115	  }
   116	  const broker = matchingBrokers[0]!;
   117	  if (!verifyCanonical(claims, args.attestation.signature, broker.publicKey)) {
   118	    return { ok: false, reason: 'native invocation attestation signature is invalid' };
   119	  }
   120	  const now = args.now ?? Date.now();
   121	  const issuedAt = Date.parse(claims.issuedAt);
   122	  const expiresAt = Date.parse(claims.expiresAt);
   123	  if (issuedAt > now + 5_000 || expiresAt <= issuedAt || expiresAt - issuedAt > 120_000
   124	    || ((args.requireFresh ?? true) && expiresAt < now)) {
   125	    return { ok: false, reason: 'native invocation attestation is expired or outside the bounded issuance window' };
   126	  }
   127	  for (const field of [
   128	    'host',
   129	    'storyId',
   130	    'agent',
   131	    'lane',
   132	    'reviewRunId',
   133	    'writerSessionId',
   134	    'dispatchPromptDigest',
   135	    'dispatchBindingDigest',
   136	    'hostRenderIdentityDigest',
   137	  ] as const) {
   138	    if (claims[field] !== args.expected[field]) {
   139	      return { ok: false, reason: `native invocation attestation ${field} does not match the exact review invocation` };
   140	    }
   141	  }
   142	  return {
   143	    ok: true,
   144	    broker,
   145	    attestationDigest: `sha256:${digestCanonicalJson(args.attestation)}`,
   146	  };
