   195	export function readNativeReviewInvocationAttestationFromFd(
   196	  env: NodeJS.ProcessEnv = process.env,
   197	): SignedNativeReviewInvocationAttestation | null {
   198	  const rawFd = env.LATTICE_NATIVE_REVIEW_ATTESTATION_FD?.trim();
   199	  if (!rawFd) return null;
   200	  const fd = Number(rawFd);
   201	  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
   202	    throw new Error('native invocation attestation fd must be an inherited descriptor between 3 and 255');
   203	  }
   204	  const raw = readFileSync(fd, 'utf8');
